import { useTranslation } from "react-i18next";
import { refundableOrders } from "../lib/refundEligibility";

export function OrderActions({ orders, now, onTrack, onRefund }: Props) {
  const { t } = useTranslation();
  const eligible = refundableOrders(orders, now);
  return (
    <Menu>
      <MenuItem onClick={onTrack}>Track package</MenuItem>
      <MenuItem disabled={eligible.length === 0} onClick={onRefund}>
        {t("orders.requestRefund")}
      </MenuItem>
    </Menu>
  );
}

