import type { Order } from "./types";

const REFUND_WINDOW_DAYS = 30;

function withinWindow(order: Order, now: Date): boolean {
  const ageDays = (now.getTime() - order.deliveredAt.getTime()) / 86_400_000;
  return ageDays <= REFUND_WINDOW_DAYS;
}

export const refundableOrders = (
  orders: Order[],
  now: Date,
): Order[] => {
  const candidates = orders.filter(
    (o) => o.status === "Delivered" && o.refundedAt == null && o.isGift === false && withinWindow(o, now),
  );
  const newest = Math.max(...candidates.map((o) => o.deliveredAt.getTime()));
  return candidates.filter((o) => o.deliveredAt.getTime() === newest);
};

